    public InspectionLot addToResults( UUID parentId, InspectionResult addTo ) {
	    LOGGER.info("handling AssignResultsToInspectionLotEvent - " );
	    
	    InspectionLot parentEntity = repository.findById(parentId).get();
	    InspectionResult child = registry.project( InspectionResult.class, addTo.getInspectionResultId());
	    
	    parentEntity.getResults().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

