	    InspectionLot parentEntity = repository.findById(parentId).get();
	    InspectionResult child = registry.project( InspectionResult.class, removeFrom.getInspectionResultId());
	    
	    parentEntity.getResults().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
